    "Light or motion seems too much, or the player gets overexcited": "A luz ou o movimento parecem excessivos, ou a pessoa fica agitada demais",
    "Set {path} to {subtle} or {none}.": "Coloque {path} em {subtle} ou {none}.",
    "No sound": "Sem som",
